// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { addProductToCart, placeOrder } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8080");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(70000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(`${baseUrl}/logout`);
    await page.goto(`${baseUrl}/product/6E92ZMYYFZ`);
    await addProductToCart(page, "2");

    // Badge shows the pre-checkout quantity.
    await expect(page.locator('#cart-count-badge')).toHaveText('2');
    await expect(page.getByRole("link", { name: "Cart icon" })).toContainText("2");

    await placeOrder(page);
    await expect(page).toHaveURL(`${baseUrl}/cart/checkout`);
    await expect(page.getByRole('heading', { name: 'Your order is complete!' })).toBeVisible();
    // Mug $8.99 x 2 = $17.98 subtotal + $8.99 shipping = $26.97.
    await expect(page.getByRole('main')).toContainText('$26.97');

    // Placing the order empties the cart, so the badge must be hidden again.
    await expect(page.locator('#cart-count-badge')).toBeHidden();

    await page.getByRole("button", { name: "Continue Shopping" }).click();
    await page.waitForLoadState('networkidle');
    await expect(page).toHaveURL(`${baseUrl}/`);
    // ...and must stay hidden on the next page the shopper lands on.
    await expect(page.locator('#cart-count-badge')).toBeHidden();
    await expect(page.getByRole("link", { name: "Cart icon" })).not.toContainText("2");
});
